// Shared constants for both pages. Load text.js and wfp.js before this file. Pain data comes from wfp.js (generated by scripts/fetch_paintrack.py).
var OZ_TO_G = 28.35;
var COOKING_YIELD = 0.75;           // USDA ARS: cooked weight as a share of raw
var LIVE_LB_PER_YEAR = 61.1e9;      // USDA NASS 2024: lb of live chickens produced in the U.S.
var BIRDS_PER_YEAR = 9.33e9;        // USDA NASS 2024: chickens produced
var LIVE_LB = LIVE_LB_PER_YEAR / BIRDS_PER_YEAR;   // 6.55 lb per bird
var DRESSING = 0.735, DRESSING_LO = 0.72, DRESSING_HI = 0.75;   // University of Wisconsin Extension: 72–75% for a 6.5 lb commercial broiler
var EDIBLE_SHARE = 0.68;            // USDA SR28 item 05006, whole broiler raw, meat and skin: 32% refuse (bone)
var EDIBLE_MEAT_ONLY = 0.48;        // USDA SR28 item 05011, whole broiler raw, meat only: 52% refuse (bone and skin)

// The two production systems the Welfare Footprint Project modelled.
var SYSTEMS = {
  conventional: { label: TEXT.systems.conventional.label, liveG: LIVE_LB * 453.6, liveTag: 'NASS', lifetimeDays: 47, lifeTag: 'NCC' },
  reformed:     { label: TEXT.systems.reformed.label, liveG: 2500, liveTag: 'WFP', lifetimeDays: 56, lifeTag: 'WFP' }
};
var LEVELS = ['annoying', 'hurtful', 'disabling', 'excruciating'];
var LEVEL_NAMES = { annoying: 'Annoying', hurtful: 'Hurtful', disabling: 'Disabling', excruciating: 'Excruciating' };
var LEVEL_DEFS = TEXT.intensities;
// URL-safe name of a harm, used for docs/harms/<slug>.html.
function harmSlug(name) { return name.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, ''); }
// Label and description for one Pain-Track burden (a kind of a harm), from text.js; falls back to the raw name.
function partLabel(raw) { var t = TEXT.parts[raw]; return t ? t : [raw.replace(/^F\d+\.\s*/, ''), '']; }
function harmWhat(c) { return TEXT.harms[c.name] || c.what; }   // description from text.js, else from the data file
function fmt(template, vars) { return template.replace(/\{(\w+)\}/g, function (m, k) { return vars[k] !== undefined ? vars[k] : m; }); }

// Everything the pages need for one serving of cooked chicken, in grams.
function servingStats(cookedG, sysKey) {
  var sys = SYSTEMS[sysKey];
  var data = WFP.systems[sysKey];
  var rawG = cookedG / COOKING_YIELD;
  var rawPerBird = sys.liveG * DRESSING * EDIBLE_SHARE;
  var rawPerBirdHi = sys.liveG * DRESSING_HI * EDIBLE_SHARE;       // most meat per bird: high dressing, skin counted
  var rawPerBirdLo = sys.liveG * DRESSING_LO * EDIBLE_MEAT_ONLY;   // least: low dressing, meat only
  var lifetimes = rawG / rawPerBird;
  var lifetimesLo = rawG / rawPerBirdHi, lifetimesHi = rawG / rawPerBirdLo;
  // Scale a per-bird quantity with its interval to this serving, combining the weight-side
  // and harm-side uncertainties as independent relative errors (in quadrature).
  function scaled(mean, lo, hi) {
    if (!(mean > 0)) return { hours: 0, lo: 0, hi: 0 };
    var rlH = (mean - lo) / mean, rhH = (hi - mean) / mean;
    var rlF = (lifetimes - lifetimesLo) / lifetimes, rhF = (lifetimesHi - lifetimes) / lifetimes;
    var h = mean * lifetimes;
    return { hours: h, lo: Math.max(0, h * (1 - Math.sqrt(rlH * rlH + rlF * rlF))), hi: h * (1 + Math.sqrt(rhH * rhH + rhF * rhF)) };
  }
  var causes = data.causes.map(function (c) {
    var x = scaled(c.total, c.total_lo, c.total_hi);
    // The kinds within a harm (e.g. each gait score of lameness), from the Pain-Track burdens.
    var parts = (c.parts || []).map(function (pt) {
      var y = scaled(pt.total, pt.total_lo, pt.total_hi), lab = partLabel(pt.name);
      return { raw: pt.name, name: lab[0], what: lab[1], hours: y.hours, lo: y.lo, hi: y.hi, perBird: pt.total, perBirdLo: pt.total_lo, perBirdHi: pt.total_hi,
               prevalence: pt.prevalence };
    });
    return { name: c.name, what: harmWhat(c), hours: x.hours, lo: x.lo, hi: x.hi, perBird: c.total, perBirdLo: c.total_lo, perBirdHi: c.total_hi, parts: parts };
  });
  // The published totals by intensity cover life on the farm; the slaughter harm (from the project's
  // stunning Pain-Tracks) is added on top, its interval combined in quadrature.
  var slaughter = data.causes.filter(function (c) { return c.scenario; })[0];
  var levels = LEVELS.map(function (l) {
    var p = data.published[l], mean = p.mean, lo = p.lo, hi = p.hi;
    if (slaughter) {
      var sdP = (p.hi - p.lo) / 2 / 1.645, sdS = (slaughter.hi[l] - slaughter.lo[l]) / 2 / 1.645, sd = Math.sqrt(sdP * sdP + sdS * sdS);
      mean += slaughter.mean[l]; lo = Math.max(0, mean - 1.645 * sd); hi = mean + 1.645 * sd;
    }
    var x = scaled(mean, lo, hi);
    return { key: l, name: LEVEL_NAMES[l], def: LEVEL_DEFS[l], hours: x.hours, lo: x.lo, hi: x.hi, perBird: mean, perBirdLo: lo, perBirdHi: hi };
  });
  var allPerBird = data.causes.reduce(function (s, c) { return s + c.total; }, 0);
  var allSd = Math.sqrt(LEVELS.reduce(function (s, l) { var sd = (data.published[l].hi - data.published[l].lo) / 2 / 1.645; return s + sd * sd; }, 0));
  if (slaughter) { var sdSl = (slaughter.total_hi - slaughter.total_lo) / 2 / 1.645; allSd = Math.sqrt(allSd * allSd + sdSl * sdSl); }
  var allLo = Math.max(0, allPerBird - 1.645 * allSd), allHi = allPerBird + 1.645 * allSd;
  var all = scaled(allPerBird, allLo, allHi);
  return { cookedG: cookedG, rawG: rawG, rawPerBird: rawPerBird, rawPerBirdLo: rawPerBirdLo, rawPerBirdHi: rawPerBirdHi,
           lifetimes: lifetimes, lifetimesLo: lifetimesLo, lifetimesHi: lifetimesHi,
           days: lifetimes * sys.lifetimeDays, daysLo: lifetimesLo * sys.lifetimeDays, daysHi: lifetimesHi * sys.lifetimeDays, lifetimeDays: sys.lifetimeDays,
           causes: causes, levels: levels, allHours: all.hours, allLo: all.lo, allHi: all.hi,
           allPerBird: allPerBird, allPerBirdLo: allLo, allPerBirdHi: allHi, scaled: scaled };
}
